// Top-level domains accepted for e-mail and website detection (SPEC rule 3/4): the IANA root-zone list
// (src/engine/extract/iana-tlds.ts, generated by scripts/update-tlds.mjs; owner approved the download 2026-10-16, D44).
// It replaced the curated P3 list (D32); tld.test.ts keeps that list as a regression check (every curated entry must
// still be a valid TLD — 5 were not: hotel, job, architect, 網絡, 日本). Unicode TLDs (рф, 中国, السعودية …) are matched
// through their punycode form.
import { IANA_TLDS } from './iana-tlds';

export const TLDS: ReadonlySet<string> = new Set(IANA_TLDS.split(/\s+/).filter(Boolean));

// RFC 3492 punycode (encode only) for one label.
const BASE = 36;
const adapt = (delta: number, points: number, first: boolean): number => {
  let d = first ? Math.floor(delta / 700) : delta >> 1;
  d += Math.floor(d / points);
  let k = 0;
  while (d > 455) {
    d = Math.floor(d / 35);
    k += BASE;
  }
  return k + Math.floor((36 * d) / (d + 38));
};
const digit = (d: number) => String.fromCharCode(d + 22 + 75 * (d < 26 ? 1 : 0));
export function punycodeLabel(label: string): string {
  const cps = [...label.normalize('NFC').toLowerCase()].map((c) => c.codePointAt(0) as number);
  let out = cps.filter((c) => c < 0x80).map((c) => String.fromCharCode(c)).join('');
  const basic = out.length;
  let h = basic;
  if (basic > 0) out += '-';
  let n = 128;
  let delta = 0;
  let bias = 72;
  while (h < cps.length) {
    const m = Math.min(...cps.filter((c) => c >= n));
    delta += (m - n) * (h + 1);
    n = m;
    for (const c of cps) {
      if (c < n) delta++;
      if (c !== n) continue;
      let q = delta;
      for (let k = BASE; ; k += BASE) {
        const t = k <= bias ? 1 : k >= bias + 26 ? 26 : k - bias;
        if (q < t) break;
        out += digit(t + ((q - t) % (BASE - t)));
        q = Math.floor((q - t) / (BASE - t));
      }
      out += digit(q);
      bias = adapt(delta, h + 1, h === basic);
      delta = 0;
      h++;
    }
    delta++;
    n++;
  }
  return `xn--${out}`;
}

/** True when the last label of a host is a TLD in the IANA snapshot (Unicode TLDs via punycode). */
export function knownTld(host: string): boolean {
  const last = host.toLowerCase().replace(/\.$/, '').split('.').pop() ?? '';
  if (TLDS.has(last)) return true;
  return /[^\x00-\x7f]/.test(last) && TLDS.has(punycodeLabel(last));
}

