/** Second-level "public suffix" labels below a ccTLD (acme.co.uk → stem "acme"). */
export const SECOND_LEVEL = new Set(`co com net org gov edu ac or ne go gr lg ad ed biz info ltd plc me nom gen firm sch`.split(/\s+/));
